// StatePolicy trait implementation
// ======================================================================

impl StatePolicy for StatechartHostInvokerPolicy {
    type State = StatechartHostInvokerState;
    type Event = StatechartHostInvokerEvent;
    // EventSchema native lowering: `()` = schemaless (dynamic
    // `_event.data` baseline); a `<Machine>Payload` sum is emitted when a
    // transition guard reads a typed `_event.data.<field>` (NL→IR C1 Path A).
    type Payload = ();
    type Hal = sce_rust_runtime::StdHal;

    // W3C SCXML Appendix D internalQueue / externalQueue. Under no_std the
    // depth is the per-document `<scxml sce:capacity>` / deploy value (emitted
    // as the const consumed below); absent a declared capacity the bare form
    // inherits the runtime default `MAX_EVENT_QUEUE_DEPTH` (the single source of
    // the default). Inert under std (`VecDeque`), so this one emission compiles
    // on both runtime profiles.
    type EventQueue = sce_rust_runtime::EventQueueManager<
        sce_rust_runtime::EventWithMetadata<Self::Event, Self::Payload>,
    >;

    // W3C SCXML 6.3: the delayed-send scheduler keeps a per-entry `send_id` only
    // so `<cancel sendid>` can find and drop the matching entry; the timer-fire
    // drain never reads it. A document with no `<cancel>` therefore emits the
    // zero-size `ElidedSendId`, shedding the scheduler ring's per-entry
    // `heapless::String<256>` (~256 B x MAX_SCHEDULED_EVENTS) under no_std --
    // dead weight with no cancel reader. A cancelling document keeps the
    // load-bearing `SceString`. Behaviour-preserving under std either way, so
    // this one emission compiles on both runtime profiles. Mirrors the
    // EventQueue per-machine sizing lever above.
    type ScheduledSendId = sce_rust_runtime::ElidedSendId;

    // W3C SCXML feature flags
    const HAS_PARALLEL_STATES: bool = false;
    const NEEDS_SCRIPT_ENGINE: bool = true;
    const NEEDS_DATA_MODEL_INIT: bool = true;
    // The same fact the generate manifest publishes as `needs_event_scheduler`.
    // A `build.rs` consumer never sees that manifest — `compile_scxml` returns
    // `()` — so without this constant a host had no route to the knowledge that
    // its driving loop must call `tick()` rather than `step()`.
    const NEEDS_EVENT_SCHEDULER: bool = false;
    const HAS_EXTERNAL_EVENT_FLAG: bool = true;
    // §scxml-6.4: gates the engine's macrostep-end call into
    // `execute_pending_invokes`. §scxml-6.4.1 unsupported-type invokes need
    // it too — that call site is where their error.execution is raised.
    const HAS_INVOKE_SUPPORT: bool = true;

    // ======================================================================
    // Static metadata methods (W3C SCXML document structure)
    // ======================================================================

    fn initial_state() -> Self::State {
        // The runtime entry state and the type's `Default` derive are one
        // concept, sourced from one computation (`default_state_id`) so
        // they can never diverge: `<scxml initial>`, or the first sorted
        // state when the initial attribute is unset.
        StatechartHostInvokerState::Invoking
    }

    fn is_final_state(state: Self::State) -> bool {
        match state {
            _ => false,
        }
    }

    fn get_parent(state: Self::State) -> Option<Self::State> {
        match state {
            _ => None,
        }
    }

    fn is_compound_state(state: Self::State) -> bool {
        match state {
            _ => false,
        }
    }

    fn is_descendant_of(desc: Self::State, anc: Self::State) -> bool {
        let mut current = desc;
        loop {
            match Self::get_parent(current) {
                None => return false,
                Some(parent) => {
                    if parent == anc {
                        return true;
                    }
                    current = parent;
                }
            }
        }
    }

    fn get_document_order(state: Self::State) -> u32 {
        match state {
            StatechartHostInvokerState::Done => 1,
            StatechartHostInvokerState::Invoking => 0,
        }
    }

    fn get_event_name(event: Self::Event) -> &'static str {
        match event {
            StatechartHostInvokerEvent::DoneInvokeProbe => "done.invoke.probe",
            StatechartHostInvokerEvent::ErrorExecution => "error.execution",
            StatechartHostInvokerEvent::Leave => "leave",
            StatechartHostInvokerEvent::Null => "",
        }
    }

    fn get_event_from_name(name: &str) -> Option<Self::Event> {
        match name {
            "done.invoke.probe" => Some(StatechartHostInvokerEvent::DoneInvokeProbe),
            "error.execution" => Some(StatechartHostInvokerEvent::ErrorExecution),
            "leave" => Some(StatechartHostInvokerEvent::Leave),
            _ => None,
        }
    }

    fn get_state_name(state: Self::State) -> &'static str {
        match state {
            StatechartHostInvokerState::Done => "done",
            StatechartHostInvokerState::Invoking => "invoking",
        }
    }

    fn null_event() -> Self::Event {
        StatechartHostInvokerEvent::Null
    }

    // W3C SCXML 3.6: Get initial children of a compound state
    //
    // SCE Protocol-Synthesis RFC §synth-5-J-2: return type is the runtime crate's
    // [`StateChain`] alias and the body uses `state_chain_from_slice` instead of
    // `vec![...]` so the emitted code compiles under `--no-std` (`vec!` is a
    // std-only macro; heapless has no equivalent).
    fn get_initial_children(
        state: Self::State,
    ) -> ::sce_rust_runtime::helpers::hierarchy::StateChain<Self::State> {
        match state {
            _ => ::sce_rust_runtime::helpers::hierarchy::new_chain(),
        }
    }

    // W3C SCXML 3.11: Get initial or history-restored child
    fn get_initial_or_history_child(&self, state: Self::State) -> Self::State {
        match state {
            _ => state,
        }
    }

    // ======================================================================
    // Mutable field accessors
    // ======================================================================

    fn last_transition_is_internal(&self) -> bool {
        self.last_transition_is_internal
    }

    fn set_last_transition_is_internal(&mut self, value: bool) {
        self.last_transition_is_internal = value;
    }

    fn last_transition_is_targetless(&self) -> bool {
        self.last_transition_is_targetless
    }

    fn set_last_transition_is_targetless(&mut self, value: bool) {
        self.last_transition_is_targetless = value;
    }

    fn last_transition_source_state(&self) -> Self::State {
        self.last_transition_source_state
    }

    fn set_last_transition_source_state(&mut self, state: Self::State) {
        self.last_transition_source_state = state;
    }

    fn set_next_event_is_external(&mut self, value: bool) {
        self.next_event_is_external = value;
    }

    // W3C SCXML 5.10: Populate pending event metadata from EventWithMetadata
    // Ports C++ EventMetadataHelper::populatePolicyFromMetadata
    fn populate_event_metadata(&mut self, metadata: &sce_rust_runtime::EventMetadata) {
        self.pending_event_data = metadata.data.clone();
        self.pending_event_type =
            ::sce_rust_runtime::sce_string_from_str(metadata.event_type.as_str());
        self.pending_event_sendid = metadata.send_id.clone();
        self.pending_event_origin = metadata.origin.clone();
        self.pending_event_origintype = metadata.origin_type.clone();
        self.pending_event_invokeid = metadata.invoke_id.clone();
    }

    // W3C SCXML 5.10: Clear pending event metadata after transition processing
    // Ports C++ EventMetadataHelper::clearPolicyMetadata
    fn clear_event_metadata(&mut self) {
        self.pending_event_name.clear();
        self.pending_event_data.clear();
        self.pending_event_type.clear();
        self.pending_event_sendid.clear();
        self.pending_event_origin.clear();
        self.pending_event_origintype.clear();
        self.pending_event_invokeid.clear();
    }

    // ======================================================================
    // Instance methods - generated executable content
    // ======================================================================

    // W3C SCXML 3.7: Execute <onentry> actions for a state
    #[doc = "SCE-MAP: statechart_host_invoker.scxml:26 :: _machine"]
    // SCE-MAP: statechart_host_invoker.scxml:26 :: _machine
    fn execute_entry_actions(
        &mut self,
        state: Self::State,
        engine: &mut sce_rust_runtime::Engine<Self>,
        path_child: Option<Self::State>,
    ) {
        // Only a `<parallel>` machine descends into defaults here — see the
        // blocks at the end of this function — so a machine without one has
        // nothing to tell an ancestor entry from a target entry.
        let _ = path_child;
        match state {
            StatechartHostInvokerState::Done => {
                // SCE-MAP: statechart_host_invoker.scxml:56 :: done :: _state_body
                // W3C SCXML 3.8: onentry block 1/1
                // Labeled block allows actions to break out on error (W3C 3.8: error stops block)
                'action_block: {
                    {
                        // W3C SCXML 5.3: <assign location="ended">
                        self.ensure_script_engine();
                        let sid = self.session_id.as_ref().unwrap().clone();
                        let se = self.script_engine.clone();
                        let se: &dyn sce_rust_runtime::IScriptEngine = &*se;
                        let expr = "_scxml_add(ended, 1)";
                        // W3C SCXML 5.3: Assign via execute_script preserves Lua reference identity for
                        // table values (e.g. `Var2 = _event` — test 329 requires `Var2 == _event`). Going
                        // through evaluate_expression + set_variable would round-trip through ScriptValue
                        // and create a fresh table, breaking reference equality.
                        let assign_script = format!("{} = {}", "ended", expr);
                        if let Err(e) = se.execute_script(&sid, &assign_script) {
                            ::sce_rust_runtime::sce_log_error!("Assign failed for 'ended': {}", e);
                            engine.raise(sce_rust_runtime::EventWithMetadata::platform_error(
                                StatechartHostInvokerEvent::ErrorExecution,
                                "<assign> to 'ended' failed",
                            ));
                            // W3C SCXML 3.8/3.9: Error stops subsequent actions in this onentry/onexit block
                            break 'action_block;
                        }
                    }
                }
            }
            StatechartHostInvokerState::Invoking => {
                // SCE-MAP: statechart_host_invoker.scxml:36 :: invoking :: _state_body
                // W3C SCXML 3.8: onentry block 1/1
                // Labeled block allows actions to break out on error (W3C 3.8: error stops block)
                'action_block: {
                    {
                        // W3C SCXML 5.3: <assign location="entered">
                        self.ensure_script_engine();
                        let sid = self.session_id.as_ref().unwrap().clone();
                        let se = self.script_engine.clone();
                        let se: &dyn sce_rust_runtime::IScriptEngine = &*se;
                        let expr = "_scxml_add(entered, 1)";
                        // W3C SCXML 5.3: Assign via execute_script preserves Lua reference identity for
                        // table values (e.g. `Var2 = _event` — test 329 requires `Var2 == _event`). Going
                        // through evaluate_expression + set_variable would round-trip through ScriptValue
                        // and create a fresh table, breaking reference equality.
                        let assign_script = format!("{} = {}", "entered", expr);
                        if let Err(e) = se.execute_script(&sid, &assign_script) {
                            ::sce_rust_runtime::sce_log_error!(
                                "Assign failed for 'entered': {}",
                                e
                            );
                            engine.raise(sce_rust_runtime::EventWithMetadata::platform_error(
                                StatechartHostInvokerEvent::ErrorExecution,
                                "<assign> to 'entered' failed",
                            ));
                            // W3C SCXML 3.8/3.9: Error stops subsequent actions in this onentry/onexit block
                            break 'action_block;
                        }
                    }
                }
                // §scxml-6.4.1: `type` names an invoker the HOST declared to
                // this build. Deferred exactly like the refused arm above and
                // for the same reason — §scxml-6.4 orders invokes after the
                // macrostep settles, and a state that exits first must never
                // have started anything. Only the execute step differs: a
                // dispatch into the host's invoker instead of a raise.
                {
                    let generated_invoke_id =
                        format!("{}.{}.probe", "invoking", self as *const _ as usize);
                    sce_rust_runtime::invoke::defer_invoke(
                        &mut self.pending_invokes,
                        sce_rust_runtime::invoke::PendingInvoke {
                            invoke_id: generated_invoke_id,
                            state: StatechartHostInvokerState::Invoking,
                        },
                    );
                }
            }
            _ => {}
        }
    }

    // W3C SCXML 3.8: Execute <onexit> actions for a state
    #[doc = "SCE-MAP: statechart_host_invoker.scxml:26 :: _machine"]
    // SCE-MAP: statechart_host_invoker.scxml:26 :: _machine
    fn execute_exit_actions(
        &mut self,
        state: Self::State,
        engine: &mut sce_rust_runtime::Engine<Self>,
        pre_transition_active: &[Self::State],
    ) {
        // W3C SCXML 6.4: Cancel pending invokes and cleanup active children on state exit
        match state {
            StatechartHostInvokerState::Invoking => {
                // W3C SCXML 6.4: Cancel pending invokes for exited state.
                // Covers §scxml-6.4.1 entries: an invoke whose state exits
                // before the macrostep ends never runs, so it raises nothing.
                sce_rust_runtime::invoke::cancel_invokes_for_state(
                    &mut self.pending_invokes,
                    StatechartHostInvokerState::Invoking,
                );
                // §scxml-6.4: the host's invocation ends with the state that
                // started it. Unconditional here: the engine knows whether
                // this one ever started and stays silent when it did not, so
                // the emitted chain does not need its own bookkeeping.
                engine.cancel_host_invoke("x-sce-host", "probe");
            }
            _ => {}
        }
        match state {
            _ => {}
        }
    }

    // W3C SCXML 3.13: Evaluate guards and take a matching transition
    #[doc = "SCE-MAP: statechart_host_invoker.scxml:26 :: _machine"]
    // SCE-MAP: statechart_host_invoker.scxml:26 :: _machine
    fn process_transition(
        &mut self,
        current_state: &mut Self::State,
        event: Self::Event,
        engine: &mut sce_rust_runtime::Engine<Self>,
    ) -> bool {
        let mut transition_taken = false;

        // W3C SCXML 5.10: Ensure script engine and set _event for guard evaluation
        self.ensure_script_engine();
        if event != Self::null_event() {
            let event_name = Self::get_event_name(event);
            self.pending_event_name = event_name.to_string();
            // W3C SCXML 5.10.1: Classify event type (ports C++ EventTypeHelper::classifyEventType)
            let event_type = if event_name.starts_with("error.") || event_name.starts_with("done.")
            {
                "platform"
            } else if self.next_event_is_external {
                self.next_event_is_external = false;
                "external"
            } else {
                "internal"
            };
            self.pending_event_type = event_type.to_string();
            // W3C SCXML 5.10: Set _event with all available metadata fields
            let ev_data: &str = &self.pending_event_data;
            let ev_sendid: &str = &self.pending_event_sendid;
            let ev_origin: &str = &self.pending_event_origin;
            let ev_origintype: &str = &self.pending_event_origintype;
            let ev_invokeid: &str = &self.pending_event_invokeid;
            self.set_current_event_in_script_engine(
                event_name,
                ev_data,
                event_type,
                ev_sendid,
                ev_origin,
                ev_origintype,
                ev_invokeid,
            );
        }

        // Flat state machine: no hierarchy, direct transition check
        self.try_transition_in_state(
            *current_state,
            event,
            current_state,
            &mut transition_taken,
            engine,
        );

        transition_taken
    }

    // W3C SCXML 3.13: Execute transition actions (called between exit and entry)
    #[doc = "SCE-MAP: statechart_host_invoker.scxml:26 :: _machine"]
    // SCE-MAP: statechart_host_invoker.scxml:26 :: _machine
    fn execute_transition_actions(&mut self, engine: &mut sce_rust_runtime::Engine<Self>) {
        if !self.has_transition_actions {
            return;
        }

        // Switch on source state, then transition index
        match self.last_transition_source_state {
            StatechartHostInvokerState::Invoking => {
                match self.last_transition_index {
                    0 => {
                        // SCE-MAP: statechart_host_invoker.scxml:45 :: invoking :: _transition_0
                        // W3C SCXML 3.13: Transition 0 actions

                        {
                            // W3C SCXML 5.3: <assign location="started">
                            self.ensure_script_engine();
                            let sid = self.session_id.as_ref().unwrap().clone();
                            let se = self.script_engine.clone();
                            let se: &dyn sce_rust_runtime::IScriptEngine = &*se;
                            let expr = "_scxml_add(started, 1)";
                            // W3C SCXML 5.3: Assign via execute_script preserves Lua reference identity for
                            // table values (e.g. `Var2 = _event` — test 329 requires `Var2 == _event`). Going
                            // through evaluate_expression + set_variable would round-trip through ScriptValue
                            // and create a fresh table, breaking reference equality.
                            let assign_script = format!("{} = {}", "started", expr);
                            if let Err(e) = se.execute_script(&sid, &assign_script) {
                                ::sce_rust_runtime::sce_log_error!(
                                    "Assign failed for 'started': {}",
                                    e
                                );
                                engine.raise(sce_rust_runtime::EventWithMetadata::platform_error(
                                    StatechartHostInvokerEvent::ErrorExecution,
                                    "<assign> to 'started' failed",
                                ));
                            }
                        }
                    }
                    1 => {
                        // SCE-MAP: statechart_host_invoker.scxml:48 :: invoking :: _transition_1
                        // W3C SCXML 3.13: Transition 1 actions

                        {
                            // W3C SCXML 5.3: <assign location="refused">
                            self.ensure_script_engine();
                            let sid = self.session_id.as_ref().unwrap().clone();
                            let se = self.script_engine.clone();
                            let se: &dyn sce_rust_runtime::IScriptEngine = &*se;
                            let expr = "_scxml_add(refused, 1)";
                            // W3C SCXML 5.3: Assign via execute_script preserves Lua reference identity for
                            // table values (e.g. `Var2 = _event` — test 329 requires `Var2 == _event`). Going
                            // through evaluate_expression + set_variable would round-trip through ScriptValue
                            // and create a fresh table, breaking reference equality.
                            let assign_script = format!("{} = {}", "refused", expr);
                            if let Err(e) = se.execute_script(&sid, &assign_script) {
                                ::sce_rust_runtime::sce_log_error!(
                                    "Assign failed for 'refused': {}",
                                    e
                                );
                                engine.raise(sce_rust_runtime::EventWithMetadata::platform_error(
                                    StatechartHostInvokerEvent::ErrorExecution,
                                    "<assign> to 'refused' failed",
                                ));
                            }
                        }
                    }
                    _ => {}
                }
            }
            _ => {}
        }

        // Reset flags after execution
        self.has_transition_actions = false;
    }
    // W3C SCXML 5.2/5.3: Datamodel initialization with error.execution support
    // Delegates to inherent impl method (matches C++ initializeDataModel pattern)
    fn initialize_data_model(&mut self, engine: &mut Engine<Self>) {
        self.do_initialize_data_model(engine);
    }

    // W3C SCXML 6.4: Execute pending invokes at macrostep end
    fn execute_pending_invokes(&mut self, engine: &mut Engine<Self>) {
        self.do_execute_pending_invokes(engine);
    }
}

// ======================================================================
// Helper impl block (try_transition_in_state, conflict resolution, etc.)
// ======================================================================

impl StatechartHostInvokerPolicy {
    // W3C SCXML 3.12: Helper method for hierarchical transition checking
    fn try_transition_in_state(
        &mut self,
        check_state: StatechartHostInvokerState,
        event: StatechartHostInvokerEvent,
        current_state: &mut StatechartHostInvokerState,
        transition_taken: &mut bool,
        engine: &mut sce_rust_runtime::Engine<Self>,
    ) -> bool {
        match check_state {
            StatechartHostInvokerState::Done => false,
            StatechartHostInvokerState::Invoking => {
                // W3C SCXML 3.12: Event-triggered transitions (document order)
                // W3C SCXML 5.9.3: Direct enum comparison
                if event == StatechartHostInvokerEvent::DoneInvokeProbe {
                    // W3C SCXML 3.4: Track transition metadata
                    self.last_transition_source_state = check_state;
                    self.last_transition_index = 0;
                    self.has_transition_actions = true;
                    self.last_transition_is_internal = true;
                    self.last_transition_is_targetless = true;

                    // W3C SCXML 5.9.2: Targetless internal transition
                    *transition_taken = true;
                    return true;
                }
                // W3C SCXML 5.9.3: Direct enum comparison
                if event == StatechartHostInvokerEvent::ErrorExecution {
                    // W3C SCXML 3.4: Track transition metadata
                    self.last_transition_source_state = check_state;
                    self.last_transition_index = 1;
                    self.has_transition_actions = true;
                    self.last_transition_is_internal = true;
                    self.last_transition_is_targetless = true;

                    // W3C SCXML 5.9.2: Targetless internal transition
                    *transition_taken = true;
                    return true;
                }
                // W3C SCXML 5.9.3: Direct enum comparison
                if event == StatechartHostInvokerEvent::Leave {
                    // W3C SCXML 3.4: Track transition metadata
                    self.last_transition_source_state = check_state;
                    self.last_transition_index = 2;
                    self.has_transition_actions = false;
                    self.last_transition_is_internal = false;
                    self.last_transition_is_targetless = false;

                    *current_state = StatechartHostInvokerState::Done;
                    *transition_taken = true;
                    return true;
                }
                false
            }
            _ => false,
        }
    }
}
